:root{
  --gold:#d9b26a;
  --gold-soft:#f0dcae;
  --ink:#f4efe4;
  --muted:#bcb09a;
  --panel:rgba(20,16,13,.74);
  --panel-solid:rgba(20,16,13,.94);
  --line:rgba(217,178,106,.28);
  --shadow:0 18px 50px rgba(0,0,0,.55);
  --font-serif:"Iowan Old Style","Palatino Linotype",Palatino,"Book Antiqua",Georgia,"Times New Roman",serif;
  --font-sans:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}

*{box-sizing:border-box}
html,body{height:100%;margin:0;padding:0}
body{
  background:#0b0a09;color:var(--ink);
  font-family:var(--font-sans);
  overflow:hidden;
  -webkit-font-smoothing:antialiased;
}
canvas{display:block}
#scene{position:fixed;inset:0;z-index:0}

#labels{position:fixed;inset:0;z-index:5;pointer-events:none;overflow:hidden}
.lbl{
  position:absolute;transform:translate(-50%,-100%);
  font-family:var(--font-sans);font-size:11.5px;letter-spacing:.06em;
  color:var(--gold-soft);white-space:nowrap;
  padding:4px 9px 4px 8px;border-radius:3px;
  background:linear-gradient(180deg,rgba(18,14,11,.82),rgba(18,14,11,.66));
  border:1px solid var(--line);
  box-shadow:0 6px 18px rgba(0,0,0,.45);
  opacity:0;transition:opacity .45s ease;
}
.lbl.on{opacity:1}
.lbl b{font-weight:600;color:#fff8e8}
.lbl i{font-style:normal;color:var(--muted);font-size:10px;margin-left:6px}
.lbl.stp{border-color:rgba(217,178,106,.75);box-shadow:0 0 0 1px rgba(217,178,106,.18),0 8px 22px rgba(0,0,0,.5)}
.lbl.stp b{color:var(--gold)}
.lbl .dot{
  position:absolute;left:50%;bottom:-26px;transform:translateX(-50%);
  width:9px;height:9px;border-radius:50%;background:var(--gold);
  border:2px solid rgba(20,15,10,.85);box-shadow:0 0 12px rgba(217,178,106,.8)
}
.lbl .stem{position:absolute;left:50%;bottom:-18px;width:1px;height:16px;background:linear-gradient(180deg,var(--gold),transparent);transform:translateX(-50%)}

/* ---------- HUD ---------- */
.hud{position:fixed;z-index:10}
.panel{
  background:var(--panel);
  backdrop-filter:blur(14px) saturate(140%);
  -webkit-backdrop-filter:blur(14px) saturate(140%);
  border:1px solid var(--line);
  border-radius:4px;
  box-shadow:var(--shadow);
}

#title{top:18px;left:20px;padding:14px 18px 13px;max-width:330px}
#title h1{
  margin:0;font-family:var(--font-serif);font-weight:600;
  font-size:25px;letter-spacing:.01em;line-height:1.05;
}
#title h1 span{color:var(--gold)}
#title .sub{margin-top:6px;font-size:11.5px;color:var(--muted);letter-spacing:.13em;text-transform:uppercase}
#title .rule{height:1px;margin:11px 0 9px;background:linear-gradient(90deg,var(--gold),rgba(217,178,106,0))}
#title .meta{font-size:11.5px;color:#cfc4ae;line-height:1.55}
#title .meta b{color:var(--gold-soft);font-weight:600}

/* ---------- Lista de paradas ---------- */
#stops{top:172px;left:20px;width:296px;max-height:calc(100vh - 300px);display:flex;flex-direction:column}
#stops .hd{
  display:flex;align-items:center;justify-content:space-between;
  padding:10px 14px;border-bottom:1px solid var(--line);
  font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);
}
#stops .hd button{
  background:none;border:1px solid var(--line);color:var(--gold-soft);
  width:22px;height:22px;border-radius:3px;cursor:pointer;font-size:12px;line-height:1;
}
#stops .hd button:hover{background:rgba(217,178,106,.14)}
#stops ol{margin:0;padding:6px 8px 10px;list-style:none;overflow-y:auto;scrollbar-width:thin}
#stops ol::-webkit-scrollbar{width:6px}
#stops ol::-webkit-scrollbar-thumb{background:rgba(217,178,106,.3);border-radius:3px}
#stops li{margin:1px 0}
#stops li button{
  width:100%;text-align:left;background:none;border:0;color:#ded5c3;cursor:pointer;
  padding:7px 8px;border-radius:3px;display:flex;gap:10px;align-items:flex-start;
  font-family:var(--font-sans);font-size:12.5px;line-height:1.35;
  transition:background .18s ease,color .18s ease;
}
#stops li button:hover{background:rgba(217,178,106,.1)}
#stops li .n{
  flex:0 0 21px;height:21px;border-radius:50%;border:1px solid var(--line);
  display:grid;place-items:center;font-size:10.5px;color:var(--gold);margin-top:1px;
}
#stops li.active button{background:rgba(217,178,106,.16);color:#fff}
#stops li.active .n{background:var(--gold);color:#1b1409;border-color:var(--gold);font-weight:700}
#stops li.done .n{color:var(--gold-soft)}
#stops .tm{margin-left:auto;font-size:10px;color:#8f8574;padding-top:3px}

/* ---------- Tarjeta de la parada ---------- */
#card{right:20px;top:18px;width:352px;padding:0;overflow:hidden}
#card .top{
  padding:15px 18px 13px;
  background:linear-gradient(135deg,rgba(217,178,106,.16),rgba(217,178,106,.02));
  border-bottom:1px solid var(--line);
}
#card .kicker{font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--gold)}
#card h2{margin:5px 0 0;font-family:var(--font-serif);font-size:22px;font-weight:600;line-height:1.15}
#card .place{margin-top:5px;font-size:11.5px;color:var(--muted)}
#card .body{padding:14px 18px 16px;font-size:13px;line-height:1.62;color:#e4dccc}
#card .body em{color:var(--gold-soft);font-style:italic}
#card .facts{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}
#card .facts span{
  font-size:10.5px;letter-spacing:.04em;padding:3px 8px;border:1px solid var(--line);
  border-radius:2px;color:#d8ccb4;background:rgba(0,0,0,.18)
}
#card .body + .facts{}
#card .nav{display:flex;gap:8px;padding:0 18px 16px}
#card .nav button{
  flex:1;background:rgba(217,178,106,.1);border:1px solid var(--line);color:var(--gold-soft);
  padding:8px;border-radius:3px;cursor:pointer;font-size:11.5px;letter-spacing:.08em;text-transform:uppercase;
  font-family:var(--font-sans);transition:background .18s
}
#card .nav button:hover{background:rgba(217,178,106,.22)}

/* ---------- Transporte ---------- */
#transport{
  left:50%;bottom:18px;transform:translateX(-50%);
  width:min(680px,calc(100vw - 40px));padding:10px 14px 12px;
}
#transport .row{display:flex;align-items:center;gap:10px}
.tbtn{
  background:rgba(217,178,106,.1);border:1px solid var(--line);color:var(--gold-soft);
  width:34px;height:32px;border-radius:3px;cursor:pointer;display:grid;place-items:center;
  font-size:13px;transition:background .18s,transform .12s
}
.tbtn:hover{background:rgba(217,178,106,.24)}
.tbtn:active{transform:scale(.94)}
.tbtn.play{width:42px;background:var(--gold);color:#1b1409;border-color:var(--gold);font-size:14px}
.tbtn.play:hover{background:#e8c179}
.tbtn.active{background:rgba(217,178,106,.32);color:#fff}
#transport .now{
  flex:1;font-family:var(--font-serif);font-size:15px;color:#efe6d4;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis
}
#transport .now small{font-family:var(--font-sans);color:var(--muted);font-size:11px;margin-left:8px;letter-spacing:.1em}
#transport .speeds{display:flex;gap:4px}
#transport .speeds button{
  background:none;border:1px solid transparent;color:var(--muted);font-size:11px;
  padding:4px 7px;border-radius:3px;cursor:pointer;font-family:var(--font-sans)
}
#transport .speeds button.on{color:var(--gold);border-color:var(--line);background:rgba(217,178,106,.12)}
#track{position:relative;height:26px;margin-top:9px;cursor:pointer}
#track .bar{position:absolute;left:0;right:0;top:11px;height:3px;background:rgba(255,255,255,.13);border-radius:2px;overflow:hidden}
#track .bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#a9834a,var(--gold));border-radius:2px}
#track .ticks{position:absolute;left:0;right:0;top:0;height:26px}
#track .tick{
  position:absolute;top:7px;width:2px;height:11px;background:rgba(255,255,255,.3);border-radius:1px;
  transform:translateX(-1px);transition:background .2s,height .2s
}
#track .tick.on{background:var(--gold-soft);height:15px;top:5px}
#track .tick.past{background:rgba(217,178,106,.75)}
#track .head{
  position:absolute;top:4px;width:13px;height:13px;border-radius:50%;background:var(--gold);
  border:2px solid #1a140d;margin-left:-6.5px;box-shadow:0 0 12px rgba(217,178,106,.7)
}
#transport .presets{display:flex;gap:5px;margin-top:8px;flex-wrap:wrap}
#transport .presets button{
  background:none;border:1px solid var(--line);color:var(--muted);font-size:10.5px;
  padding:3px 9px;border-radius:2px;cursor:pointer;letter-spacing:.05em;font-family:var(--font-sans)
}
#transport .presets button.on{color:var(--gold);background:rgba(217,178,106,.12);border-color:rgba(217,178,106,.5)}
#transport .presets .spacer{flex:1}

/* ---------- Minimapa ---------- */
#map{right:20px;bottom:18px;padding:10px}
#map .hd{display:flex;justify-content:space-between;font-size:9.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);margin-bottom:7px}
#map canvas{display:block;border-radius:3px;background:rgba(0,0,0,.3);cursor:crosshair}
#map .legend{display:flex;gap:10px;margin-top:7px;font-size:9.5px;color:#9a9082;align-items:center}
#map .legend i{width:8px;height:8px;border-radius:50%;display:inline-block;margin-right:4px;vertical-align:-1px}

/* ---------- Ayuda ---------- */
#help{
  right:20px;bottom:250px;width:300px;padding:14px 16px;display:none;z-index:12
}
#help.show{display:block}
#help h3{margin:0 0 9px;font-family:var(--font-serif);font-size:15px;font-weight:600;color:var(--gold-soft)}
#help table{width:100%;border-collapse:collapse;font-size:11.5px}
#help td{padding:3px 0;color:#d6cdbb}
#help td:first-child{color:var(--gold);width:92px;font-family:monospace;font-size:11px}
#help .close{position:absolute;right:10px;top:8px;cursor:pointer;color:var(--muted);font-size:15px}
#help .close:hover{color:#fff}
.hbtn{
  background:none;border:1px solid var(--line);color:var(--gold-soft);padding:4px 9px;
  border-radius:3px;cursor:pointer;font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;font-family:var(--font-sans)
}
.hbtn:hover{background:rgba(217,178,106,.16)}

/* ---------- Carga ---------- */
#loading{
  position:fixed;inset:0;z-index:40;background:radial-gradient(circle at 50% 40%,#1b1510,#0a0908 70%);
  display:grid;place-items:center;transition:opacity .7s ease;
}
#loading.done{opacity:0;pointer-events:none}
#loading .in{text-align:center}
#loading .mark{
  font-family:var(--font-serif);font-size:44px;color:var(--gold);letter-spacing:.02em;
  text-shadow:0 0 40px rgba(217,178,106,.35)
}
#loading .arc{margin:18px auto 14px;width:52px;height:52px;border:1px solid rgba(217,178,106,.25);border-radius:50%;border-top-color:var(--gold);animation:spin 1s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
#loading .t{font-size:11px;letter-spacing:.24em;text-transform:uppercase;color:var(--muted)}
#loading .err{margin-top:14px;font-size:12px;color:#e0a0a0;max-width:420px;line-height:1.5}

/* ---------- Responsive ---------- */
@media (max-width:1180px){
  #stops{display:none}
  #card{width:300px}
}
@media (max-width:860px){
  #title{max-width:220px;padding:10px 13px}
  #title h1{font-size:19px}
  #title .meta,#title .rule{display:none}
  #card{width:min(300px,calc(100vw - 32px));right:12px;top:12px}
  #card .body{font-size:12px;max-height:34vh;overflow:auto}
  #map{display:none}
  #transport{bottom:10px;padding:8px 10px 10px}
  #transport .now{font-size:13px}
}
@media (max-height:620px){
  #stops{display:none}
}

/* ==========================================================================
   ALHAMBRA DE GRANADA — Ruta 3D
   Motor: render, texturas procedurales, cielo, luz por hora y cámara libre
   ========================================================================== */
'use strict';

const THREE = window.THREE;
const V3 = (x, y, z) => new THREE.Vector3(x, y, z);

/* ---------------------------------------------------------------- utils */
const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, t) => a + (b - a) * t;
const smoothstep = (e0, e1, x) => { const t = clamp((x - e0) / (e1 - e0), 0, 1); return t * t * (3 - 2 * t); };
const easeInOut = t => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const easeOutCubic = t => 1 - Math.pow(1 - t, 3);
const TAU = Math.PI * 2;
const DEG = Math.PI / 180;

function rng(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = rng(20241117);

/* --------------------------------------------------------- texturas base */
function canvas2d(w, h) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return { c, x: c.getContext('2d') };
}
function toTex(c, rx, ry) {
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(rx || 1, ry || 1);
  t.anisotropy = 8;
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
function speckle(x, w, h, n, dark, light) {
  for (let i = 0; i < n; i++) {
    const px = rnd() * w, py = rnd() * h, s = 1 + rnd() * 2.2;
    x.fillStyle = rnd() > 0.5 ? dark : light;
    x.globalAlpha = 0.06 + rnd() * 0.12;
    x.fillRect(px, py, s, s);
  }
  x.globalAlpha = 1;
}

/* Tapia: earth-rammed masonry of the Nasrid walls */
function texTapia(base, dark) {
  const { c, x } = canvas2d(256, 256);
  x.fillStyle = base; x.fillRect(0, 0, 256, 256);
  for (let i = 0; i < 26; i++) {
    const y = rnd() * 256, h = 2 + rnd() * 7;
    x.fillStyle = dark; x.globalAlpha = 0.06 + rnd() * 0.09;
    x.fillRect(0, y, 256, h);
  }
  x.globalAlpha = 1;
  speckle(x, 256, 256, 2600, 'rgba(60,40,20,.9)', 'rgba(255,245,220,.9)');
  for (let i = 0; i < 14; i++) {
    x.strokeStyle = 'rgba(80,58,32,.22)'; x.lineWidth = 0.7 + rnd();
    x.beginPath();
    const px = rnd() * 256;
    x.moveTo(px, rnd() * 120);
    x.lineTo(px + (rnd() - 0.5) * 8, 140 + rnd() * 116);
    x.stroke();
  }
  return toTex(c);
}

/* Nasrid azulejo: cobalt star lattice */
function texAzulejo() {
  const { c, x } = canvas2d(256, 256);
  x.fillStyle = '#eef4f6'; x.fillRect(0, 0, 256, 256);
  const cell = 64;
  const star = (cx, cy, R, r, n, fill, stroke) => {
    x.beginPath();
    for (let i = 0; i < n * 2; i++) {
      const a = (i / (n * 2)) * TAU - Math.PI / 2;
      const rad = i % 2 ? r : R;
      const px = cx + Math.cos(a) * rad, py = cy + Math.sin(a) * rad;
      i ? x.lineTo(px, py) : x.moveTo(px, py);
    }
    x.closePath();
    if (fill) { x.fillStyle = fill; x.fill(); }
    if (stroke) { x.strokeStyle = stroke; x.lineWidth = 2; x.stroke(); }
  };
  for (let gy = 0; gy < 4; gy++) {
    for (let gx = 0; gx < 4; gx++) {
      const cx = gx * cell + cell / 2, cy = gy * cell + cell / 2;
      star(cx, cy, 25, 11.5, 8, '#1d4f9c', '#12336c');
      star(cx, cy, 13, 5.5, 8, '#f4f8fa', null);
      star(cx, cy, 6, 2.6, 8, '#2f7a53', null);
      x.strokeStyle = 'rgba(29,79,156,.35)'; x.lineWidth = 1.4;
      x.strokeRect(gx * cell + 3, gy * cell + 3, cell - 6, cell - 6);
    }
  }
  speckle(x, 256, 256, 900, 'rgba(20,40,70,.6)', 'rgba(255,255,255,.8)');
  return toTex(c);
}

/* Ashlar stone */
function texPiedra(base, joint) {
  const { c, x } = canvas2d(256, 256);
  x.fillStyle = joint; x.fillRect(0, 0, 256, 256);
  const bw = 64, bh = 32;
  for (let row = 0; row < 8; row++) {
    for (let col = -1; col < 5; col++) {
      const off = (row % 2) * bw / 2;
      const px = col * bw + off, py = row * bh;
      const shade = 0.86 + rnd() * 0.24;
      x.fillStyle = shadeHex(base, shade);
      x.fillRect(px + 1.4, py + 1.4, bw - 2.8, bh - 2.8);
    }
  }
  speckle(x, 256, 256, 1800, 'rgba(70,60,45,.7)', 'rgba(255,255,255,.7)');
  return toTex(c);
}
function shadeHex(hex, k) {
  const n = parseInt(hex.slice(1), 16);
  let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  r = clamp(Math.round(r * k), 0, 255); g = clamp(Math.round(g * k), 0, 255); b = clamp(Math.round(b * k), 0, 255);
  return `rgb(${r},${g},${b})`;
}

/* Marble paving for the courtyards */
function texMarmol() {
  const { c, x } = canvas2d(256, 256);
  x.fillStyle = '#dcd5c4'; x.fillRect(0, 0, 256, 256);
  x.strokeStyle = 'rgba(120,110,92,.5)'; x.lineWidth = 1.6;
  for (let i = 0; i <= 4; i++) {
    x.beginPath(); x.moveTo(i * 64, 0); x.lineTo(i * 64, 256); x.stroke();
    x.beginPath(); x.moveTo(0, i * 64); x.lineTo(256, i * 64); x.stroke();
  }
  x.strokeStyle = 'rgba(150,138,115,.55)'; x.lineWidth = 1.1;
  for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) {
    const cx = i * 64 + 32, cy = j * 64 + 32;
    x.beginPath();
    x.moveTo(cx, cy - 17); x.lineTo(cx + 17, cy); x.lineTo(cx, cy + 17); x.lineTo(cx - 17, cy);
    x.closePath(); x.stroke();
  }
  speckle(x, 256, 256, 2400, 'rgba(120,110,90,.55)', 'rgba(255,255,255,.85)');
  return toTex(c);
}

/* Terracotta roof tiles */
function texTeja() {
  const { c, x } = canvas2d(128, 128);
  x.fillStyle = '#9d4f34'; x.fillRect(0, 0, 128, 128);
  for (let i = 0; i < 16; i++) {
    x.fillStyle = shadeHex('#a9563a', 0.85 + rnd() * 0.3);
    x.fillRect(i * 8, 0, 7, 128);
    x.fillStyle = 'rgba(40,18,10,.3)';
    x.fillRect(i * 8 + 7, 0, 1.6, 128);
  }
  for (let i = 0; i < 128; i += 16) { x.fillStyle = 'rgba(40,18,10,.22)'; x.fillRect(0, i, 128, 2); }
  speckle(x, 128, 128, 700, 'rgba(50,24,12,.7)', 'rgba(255,220,190,.6)');
  return toTex(c);
}

/* Gravel path */
function texGrava() {
  const { c, x } = canvas2d(128, 128);
  x.fillStyle = '#c3b091'; x.fillRect(0, 0, 128, 128);
  speckle(x, 128, 128, 4200, 'rgba(110,95,70,.85)', 'rgba(255,246,225,.85)');
  return toTex(c);
}

/* Dark wood (doors, ceilings) */
function texMadera() {
  const { c, x } = canvas2d(128, 128);
  x.fillStyle = '#3b2415'; x.fillRect(0, 0, 128, 128);
  for (let i = 0; i < 30; i++) {
    x.strokeStyle = `rgba(${20 + rnd() * 40},${12 + rnd() * 20},6,.5)`;
    x.lineWidth = 0.6 + rnd() * 2;
    x.beginPath(); const px = rnd() * 128;
    x.moveTo(px, 0); x.bezierCurveTo(px + 6, 40, px - 6, 80, px + (rnd() - 0.5) * 8, 128);
    x.stroke();
  }
  return toTex(c);
