input.content:
/* ==========================================================================
   Interfaz: lista de paradas, ficha, transporte, línea de tiempo y minimapa
   ========================================================================== */

const $ = id => document.getElementById(id);
const el = {
  stopList: $('stopList'), cardTitle: $('cardTitle'), cardPlace: $('cardPlace'),
  cardBody: $('cardBody'), cardFacts: $('cardFacts'), cardKicker: $('cardKicker'),
  nowTitle: $('nowTitle'), barFill: $('barFill'), head: $('head'), ticks: $('ticks'),
  play: $('playB'), mapCanvas: $('mapCanvas'), mapCoord: $('mapCoord'),
  help: $('help'), stops: $('stops'), speedBox: $('speeds'), presetBox: $('presets')
};

/* ------------------------------------------------- lista de paradas */
const stopItems = [];
STOPS.forEach((s, i) => {
  const li = document.createElement('li');
  const b = document.createElement('button');
  b.innerHTML = `<span class="n">${i + 1}</span><span class="t">${s.title}</span>`;
  b.addEventListener('click', () => { goStop(i); });
  li.appendChild(b);
  el.stopList.appendChild(li);
  stopItems.push(li);
});

/* ---------------------------------------------------------- transporte */
function goStop(i) {
  tour.time = stopStart[clamp(i, 0, STOPS.length - 1)];
  tour.stop = i;
  syncHUD(true);
}
function nextStop() {
  const r = segmentAt(tour.time);
  let i = r.seg.stop;
  if (r.seg.type === 'travel' && r.local < 0.55) { /* ya va de camino */ }
  else i = Math.min(i + 1, STOPS.length - 1);
  goStop(i);
}
function prevStop() {
  const r = segmentAt(tour.time);
  const i = Math.max(0, r.seg.stop - 1);
  goStop(i);
}
function setPlaying(v) {
  tour.playing = v;
  el.play.textContent = v ? '❚❚' : '▶';
  el.play.classList.toggle('active', v);
}
function setSpeed(v) {
  tour.speed = v;
  Array.from(el.speedBox.children).forEach(b => b.classList.toggle('on', parseFloat(b.dataset.v) === v));
}
function setFree(v) {
  tour.free = v;
  orbit.enabled = v;
  const btn = $('freeBtn');
  if (btn) btn.classList.toggle('active', v);
  if (v) {
    const p = new THREE.Vector3(), t = new THREE.Vector3();
    poseAt(tour.time, p, t);
    camera.position.copy(p);
    camera.lookAt(t);
    orbit.syncFrom(p, t);
    setPlaying(false);
  } else {
    const p = new THREE.Vector3(), t = new THREE.Vector3();
    poseAt(tour.time, p, t);
    camera.position.copy(p);
    camera.lookAt(t);
  }
}

/* -------------------------------------------------------- HUD sincrono */
let lastStop = -1;
function syncHUD(force) {
  const r = segmentAt(tour.time);
  const s = r.seg;
  const idx = s.type === 'dwell' ? s.stop : (r.local > 0.6 ? Math.min(s.stop + 1, STOPS.length - 1) : s.stop);
  const st = STOPS[idx];

  if (idx !== lastStop || force) {
    lastStop = idx;
    el.cardKicker.textContent = `Parada ${String(idx + 1).padStart(2, '0')} / ${STOPS.length}`;
    el.cardTitle.textContent = st.title;
    el.cardPlace.textContent = st.place;
    el.cardBody.innerHTML = st.text;
    el.cardFacts.innerHTML = st.facts.map(f => `<span>${f}</span>`).join('');
    stopItems.forEach((li, i) => {
      li.classList.toggle('active', i === idx);
      li.classList.toggle('done', i < idx);
    });
  }
  const dest = STOPS[s.type === 'travel' ? Math.min(s.stop + 1, STOPS.length - 1) : s.stop];
  el.nowTitle.innerHTML = `${dest.title}<small>${s.type === 'travel' ? 'en camino' : 'en visita'}</small>`;

  const p = tour.time / T_TOTAL;
  el.barFill.style.width = (p * 100).toFixed(2) + '%';
  el.head.style.left = (p * 100).toFixed(2) + '%';
}

/* ------------------------------------------------------- línea tiempo */
{
  stopStart.forEach((t, i) => {
    const d = document.createElement('div');
    d.className = 'tick';
    d.style.left = ((t / T_TOTAL) * 100).toFixed(2) + '%';
    d.title = STOPS[i].title;
    d.addEventListener('click', ev => { ev.stopPropagation(); goStop(i); });
    el.ticks.appendChild(d);
  });
  const track = $('track');
  track.addEventListener('click', ev => {
    const r = track.getBoundingClientRect();
    const p = clamp((ev.clientX - r.left) / r.width, 0, 1);
    tour.time = p * T_TOTAL;
    syncHUD(true);
  });
}

/* --------------------------------------------------------- velocidad */
[0.5, 1, 1.5, 2].forEach(v => {
  const b = document.createElement('button');
  b.textContent = v + '×';
  b.dataset.v = v;
  b.addEventListener('click', () => setSpeed(v));
  el.speedBox.appendChild(b);
});
setSpeed(1);

/* ------------------------------------------------------ hora del día */
Object.keys(PRESETS).forEach(k => {
  const b = document.createElement('button');
  b.textContent = PRESETS[k].label;
  b.dataset.k = k;
  b.addEventListener('click', () => {
    applyPreset(k);
    Array.from(el.presetBox.children).forEach(c => c.classList.toggle('on', c.dataset.k === k));
  });
  el.presetBox.appendChild(b);
});
{
  const b = document.createElement('button');
  b.textContent = 'Vista libre';
  b.id = 'freeBtn';
  b.addEventListener('click', () => setFree(!tour.free));
  el.presetBox.appendChild(b);
  const f = document.createElement('button');
  f.textContent = 'Pantalla completa';
  f.addEventListener('click', () => {
    if (document.fullscreenElement) document.exitFullscreen();
    else document.documentElement.requestFullscreen();
  });
  el.presetBox.appendChild(f);
  const h = document.createElement('button');
  h.textContent = '?';
  h.title = 'Ayuda';
  h.addEventListener('click', () => el.help.classList.toggle('show'));
  el.presetBox.appendChild(h);
}
Array.from(el.presetBox.children).forEach(c => c.classList.toggle('on', c.dataset.k === presetActual));

/* ------------------------------------------------------------ botones */
el.play.addEventListener('click', () => {
  if (!tour.free) setPlaying(!tour.playing);
});
$('nextB').addEventListener('click', nextStop);
$('prevB').addEventListener('click', prevStop);
$('nextBtn').addEventListener('click', nextStop);
$('prevBtn').addEventListener('click', prevStop);
$('stopsToggle').addEventListener('click', () => {
  const ol = el.stopList;
  const hidden = ol.style.display === 'none';
  ol.style.display = hidden ? '' : 'none';
  $('stopsToggle').textContent = hidden ? '–' : '+';
});
el.help.querySelector('.close').addEventListener('click', () => el.help.classList.remove('show'));

/* ----------------------------------------------------------- minimapa */
const mapCtx = el.mapCanvas.getContext('2d');
const MAPW = el.mapCanvas.width, MAPH = el.mapCanvas.height;
const MB = { x0: -140, x1: 1010, z0: -150, z1: 430 };
const mscale = Math.min((MAPW - 14) / (MB.x1 - MB.x0), (MAPH - 14) / (MB.z1 - MB.z0));
const mox = (MAPW - (MB.x1 - MB.x0) * mscale) / 2;
const moz = (MAPH - (MB.z1 - MB.z0) * mscale) / 2;
const mx = x => mox + (x - MB.x0) * mscale;
const mz = z => moz + (z - MB.z0) * mscale;

const routePts = [];
for (let i = 0; i <= 240; i++) routePts.push(camCurve.getPoint(i / 240));

function drawMap() {
  const c = mapCtx;
  c.clearRect(0, 0, MAPW, MAPH);
  /* fondo */
  c.fillStyle = 'rgba(12,10,8,.55)';
  c.fillRect(0, 0, MAPW, MAPH);
  c.strokeStyle = 'rgba(217,178,106,.07)';
  c.lineWidth = 1;
  for (let x = MB.x0; x < MB.x1; x += 100) { c.beginPath(); c.moveTo(mx(x), 0); c.lineTo(mx(x), MAPH); c.stroke(); }
  for (let z = MB.z0; z < MB.z1; z += 100) { c.beginPath(); c.moveTo(0, mz(z)); c.lineTo(MAPW, mz(z)); c.stroke(); }
  /* siluetas */
  for (const s of MAP) {
    if (s.t === 'w') {
      c.beginPath();
      s.pts.forEach((p, i) => i ? c.lineTo(mx(p[0]), mz(p[1])) : c.moveTo(mx(p[0]), mz(p[1])));
      c.closePath();
      c.strokeStyle = 'rgba(226,196,140,.75)';
      c.lineWidth = 2;
      c.stroke();
      c.fillStyle = 'rgba(120,96,60,.16)';
      c.fill();
    } else if (s.t === 'r') {
      c.save();
      c.translate(mx(s.x), mz(s.z));
      c.rotate(s.rot || 0);
      c.fillStyle = 'rgba(214,190,148,.42)';
      c.strokeStyle = 'rgba(240,220,180,.6)';
      c.lineWidth = 1;
      c.fillRect(-s.w * mscale / 2, -s.d * mscale / 2, s.w * mscale, s.d * mscale);
      c.strokeRect(-s.w * mscale / 2, -s.d * mscale / 2, s.w * mscale, s.d * mscale);
      c.restore();
    } else if (s.t === 'c') {
      c.beginPath();
      c.arc(mx(s.x), mz(s.z), s.r * mscale, 0, TAU);
      c.fillStyle = 'rgba(214,190,148,.35)';
      c.strokeStyle = 'rgba(240,220,180,.6)';
      c.fill(); c.stroke();
    }
  }
  /* ruta */
  c.beginPath();
  routePts.forEach((p, i) => i ? c.lineTo(mx(p.x), mz(p.z)) : c.moveTo(mx(p.x), mz(p.z)));
  c.strokeStyle = 'rgba(217,178,106,.85)';
  c.lineWidth = 1.6;
  c.setLineDash([4, 3]);
  c.stroke();
  c.setLineDash([]);
  /* paradas */
  STOPS.forEach((s, i) => {
    const p = camPts[stopIndex[i]];
    c.beginPath();
    c.arc(mx(p.x), mz(p.z), 3, 0, TAU);
    c.fillStyle = i === lastStop ? '#f0d9a4' : 'rgba(217,178,106,.65)';
    c.fill();
  });
  /* cámara */
  const p = camera.position;
  const t = new THREE.Vector3();
  camera.getWorldDirection(t);
  const ang = Math.atan2(t.x, t.z);
  c.save();
  c.translate(mx(p.x), mz(p.z));
  c.rotate(-ang + Math.PI);
  c.fillStyle = 'rgba(255,255,255,.14)';
  c.beginPath();
  c.moveTo(0, 0);
  c.arc(0, 0, 26, -0.45, 0.45);
  c.closePath();
  c.fill();
  c.fillStyle = '#fff';
  c.beginPath();
  c.arc(0, 0, 3.2, 0, TAU);
  c.fill();
  c.restore();
  /* norte */
  c.fillStyle = 'rgba(217,178,106,.75)';
  c.font = '9px sans-serif';
  c.fillText('N', MAPW - 13, 12);
}

/* clic en el minimapa: salta a la parada más cercana */
el.mapCanvas.addEventListener('click', ev => {
  const r = el.mapCanvas.getBoundingClientRect();
  const px = (ev.clientX - r.left) * (MAPW / r.width);
  const py = (ev.clientY - r.top) * (MAPH / r.height);
  let best = -1, bd = 1e9;
  STOPS.forEach((s, i) => {
    const p = camPts[stopIndex[i]];
    const d = Math.hypot(mx(p.x) - px, mz(p.z) - py);
    if (d < bd) { bd = d; best = i; }
  });
  if (best >= 0 && bd < 26) goStop(best);
});

/* --------------------------------------------------------- teclado */
window.addEventListener('keydown', ev => {
  if (ev.target && /input|textarea/i.test(ev.target.tagName)) return;
  switch (ev.key) {
    case ' ': ev.preventDefault(); if (!tour.free) setPlaying(!tour.playing); break;
    case 'ArrowRight': nextStop(); break;
    case 'ArrowLeft': prevStop(); break;
    case 'l': case 'L': setFree(!tour.free); break;
    case 'h': case 'H': el.help.classList.toggle('show'); break;
    case 'f': case 'F':
      if (document.fullscreenElement) document.exitFullscreen();
      else document.documentElement.requestFullscreen();
      break;
  }
});

parts.text:
Now part 6: main loop, animation, resize, initialization.

- Animation loop: requestAnimationFrame, delta time.
- Update: if tour.free → orbit.update(); else → poseAt(tour.time) → set camera position/target smoothly.
- Water animation: animate the pools' material (e.g., offset a texture or move the water slightly), and the jets' scale.
- Preset blending: update applyPresetNow while blend.t < 1.
- Time advances when playing.
- If time >= T_TOTAL → loop back to 0 (or stop at the end). I'll loop: when the tour ends, reset to 0 and keep playing (nice for a kiosk). Actually better: stop at the end and show "fin"; then pressing play restarts. Let me loop with a 2 s pause? Simplest: stop at the end and set playing=false; the play button restarts from 0 if time >= T_TOTAL.
- Resize handler.
- Loading overlay removal after the first render.

Also the initial camera: set to the first stop pose and start playing after a short delay? I'll start paused at stop 1 and let the user press play. Better UX: auto-start playing after 1.2 s. I'll auto-start.

Also: performance — measure FPS? Not needed but I could show it in the map header. Let's show the coordinates in #mapCoord instead: the camera's position relative to the site, e.g., "N 41.5 · O 4.9"? Not meaningful. Let me show the current stop number and the FPS. Actually, let me show the camera height and the coordinates in a grid. Simpler: show "Parada 3/16 · 58 fps". I'll do that.

Let me write part 6.

Water animation: for the pools, I animate the material's map offset? MAT.agua has no map. Let me add a subtle animation: scale the water plane slightly or move the UV of an added ripple texture. Simplest: animate `mesh.position.y` slightly (a sine) and rotate the jets.

For a nicer effect, I'll add a "ripple" texture to the water materials: create a canvas with concentric circles (light lines) and use it as a `map` (or emissiveMap) with RepeatWrapping and animate `offset.x`. Since MAT.agua is cloned for each pool, each clone shares the same texture object (clone shares the texture) → animating offset affects all, which is fine.

Let me create the ripple texture in part 6 and assign it to all pool materials, then animate the offset.

Wait — MAT.agua clones: `MAT.agua.clone()` — the clone shares the same texture reference (textures aren't cloned by Material.clone; the map reference is copied). ✓ So one shared ripple texture works.

But the base MAT.agua (used for basinIn, water2) isn't cloned; it has no map. I'll set the map on MAT.agua before cloning... The clones were already created in part 3 (at runtime, before part 6 executes). But since the clone shares the texture reference at clone time, assigning `MAT.agua.map = rippleTex` later would NOT propagate to the clones (the clone holds a reference to the old `null`).

Solution: create the ripple texture in part 1 (before part 3) and assign it to MAT.agua there. Let me add the ripple texture to the core part... I'd have to edit 01_core.js. Simpler: in part 6, iterate over all pool meshes and set `mesh.material.map = rippleTex` (each pool's material is a distinct object: the clones for the pool plane, the acequia, and the basinIn/water2 share MAT.agua). Setting `MAT.agua.map = rippleTex` affects the base; for the clones I set `mesh.material.map = rippleTex` individually — but the clones are the pool planes (clone) and the acequia (clone); the base MAT.agua is used by basinIn and water2 (which are cylinders → UV mapping different). Setting a ripple map on a cylinder is fine.

So in part 6: `scene.userData.pools.forEach(p => { p.mesh.material.map = rippleTex; p.mesh.material.needsUpdate = true; })` and also `MAT.agua.map = rippleTex; MAT.agua.needsUpdate = true;`.

The ripple texture: concentric rings pattern, white-ish lines on transparent/dark. With MeshStandardMaterial, `map` multiplies the color → a dark texture would darken the water. Let me make the ripple texture mostly mid-gray with lighter rings → subtle modulation. Actually better to use it as a `roughnessMap`? Simpler: make a texture that's ~0.85-1.0 brightness variation, which subtly modulates the color. Good.

Let me write the ripple texture generation:
```js
function texRipple(){
  const {c,x}=canvas2d(128,128);
