    await page.waitForTimeout(900);
    const ascii = await page.evaluate(() => {
      const src = document.querySelector('canvas');
      const W = 64, H = 26;
      const c = document.createElement('canvas'); c.width = W; c.height = H;
      const x = c.getContext('2d');
      x.drawImage(src, 0, 0, W, H);
      const d = x.getImageData(0, 0, W, H).data;
      let out = '';
      for (let j = 0; j < H; j++) {
        let line = '';
        for (let i = 0; i < W; i++) {
          const k = (j * W + i) * 4;
          const r = d[k], g = d[k + 1], b = d[k + 2];
          const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
          const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
          const sat = mx === 0 ? 0 : (mx - mn) / mx;
          let ch = RAMP[Math.min(9, Math.floor(lum * 10))];
          if (sat > 0.45) ch = (b > r && b > g) ? 'B' : (g > r ? 'G' : (r > b ? 'R' : 'Y'));
          line += ch;
        }
        out += line + '\n';
      }
      return out;
    });
    console.log('\n=== t = ' + t + ' s ===');
    console.log(ascii);
  }
  if (errs.length) { console.log('\n--- errores ---'); console.log(errs.join('\n')); }
  else console.log('\nsin errores de consola');
  await browser.close();
})();

