  /* 6. reproducción */
  await page.click('#freeBtn');
  await page.click('#playB');
  await page.waitForTimeout(1200);
  const adv = await page.evaluate(() => window.__alhambra.tour.time);
  ok(adv > 0.5, 'el tiempo avanza al reproducir (' + adv.toFixed(2) + ' s)');

  /* 7. etiquetas 3D */
  const lab = await page.evaluate(() => {
    const l = [...document.querySelectorAll('#labels .lbl')];
    return { total: l.length, visibles: l.filter(x => x.classList.contains('on')).length };
  });
  ok(lab.visibles > 0, 'hay etiquetas 3D visibles (' + lab.visibles + '/' + lab.total + ')');

  /* 8. minimapa con contenido y clic */
  const mp = await page.evaluate(() => {
    const c = document.getElementById('mapCanvas');
    const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
    let n = 0; for (let i = 3; i < d.length; i += 4) if (d[i] > 10) n++;
    return n;
  });
  ok(mp > 500, 'el minimapa se redibuja durante el recorrido (' + mp + ' px)');

  console.log(errs.length ? '\nERRORES:\n' + errs.join('\n') : '\nsin errores de consola');
  await browser.close();
})();

