      boxes[i]=[Math.round(b.left),Math.round(b.top),Math.round(b.right),Math.round(b.bottom)];});
    const over=[];
    const ks=Object.keys(boxes);
    for(let i=0;i<ks.length;i++)for(let j=i+1;j<ks.length;j++){
      const A=boxes[ks[i]],B=boxes[ks[j]];
      const ox=Math.min(A[2],B[2])-Math.max(A[0],B[0]), oy=Math.min(A[3],B[3])-Math.max(A[1],B[1]);
      if(ox>2&&oy>2) over.push(ks[i]+'×'+ks[j]+' ('+ox+'x'+oy+'px)');
    }
    const out=[];
    for(let i=0;i<ks.length;i++){const b=boxes[ks[i]]; if(b[2]>innerWidth||b[3]>innerHeight||b[0]<0||b[1]<0) out.push(ks[i]+' fuera de pantalla '+b.join(','));}
    return {boxes, over, out};
  });
  console.log(vp.join('x'), JSON.stringify(r.over), r.out.length?r.out.join(' | '):'todo dentro');
  await p.close();
 }
 await b.close();
})();
